const cds = require('../../lib/cds')
const { pathToFileURL } = require('node:url')
const { path, stat, readdir, isdir, colors: { BOLD, RESET } } = cds.utils

let hmrPort = 24100

async function hasViteConfig(appPath) {
  for (const name of ['vite.config.js', 'vite.config.mjs', 'vite.config.ts']) {
    const file = await stat(path.join(appPath, name)).catch(e => e.code === 'ENOENT' ? null : Promise.reject(e))
    if (file) return true
  }
  return false
}

async function findViteApps() {
  const app = cds.env.folders.app
  const apps = []
  if (!isdir(app)) return apps
  const appRoot = path.join(cds.root, app)
  // Single-UI scenario: a vite project sits directly in app/
  if (await hasViteConfig(appRoot)) {
    apps.push({ name: '', path: appRoot, root: true })
    return apps
  }
  // Multi-UI scenario: each sub-folder of app/ may be a vite project
  const entries = await readdir(app)
  for (const entry of entries) {
    const appName = typeof entry === 'string' ? entry : entry.name
    if (!appName) continue
    const appPath = path.join(appRoot, appName)
    if (!isdir(appPath)) continue
    if (await hasViteConfig(appPath)) apps.push({ name: appName, path: appPath, root: false })
  }
  return apps
}

async function loadCreateServer(fromPath) {
  try {
      const vitePath = require.resolve('vite', { paths: [fromPath] })
      return (await import(pathToFileURL(vitePath).href)).createServer
    } catch(e) {
      if (e.code !== 'MODULE_NOT_FOUND') throw e
      /* try next path */
  }
  const relative = path.relative(cds.root, fromPath)
  throw `[cds] - Found Vite app in ${relative}, but package "vite" is not installed. Run ${BOLD}npm install vite --prefix ${relative}${RESET} to install it.`
}

function collectServicePrefixes() {
  const prefixes = new Set(['/-/', '/$batch', '/$metadata', '/health', '/favicon.ico'])
  for (const srv of cds.service.providers || []) {
    for (const ep of srv.endpoints || []) {
      if (ep.path) prefixes.add(ep.path.endsWith('/') ? ep.path : ep.path + '/')
    }
  }
  return [...prefixes]
}

cds.on('bootstrap', app => {

  let viteMiddleware = null
  app.use((req, res, next) => {
    if (viteMiddleware) return viteMiddleware(req, res, next)
    next()
  })

  cds.on('served', async () => {
    const viteApps = await findViteApps()
    if (!viteApps.length) return

    const createServer = await loadCreateServer(viteApps[0].path)

    // Build a middleware chain from all Vite servers, keyed by base path
    const viteServers = []
    const normalizeBase = base => {
      if (!base.startsWith('/')) base = `/${base}`
      return base.endsWith('/') ? base : `${base}/`
    }

    for (const viteApp of viteApps) {
      const base = viteApp.root ? '/' : normalizeBase(viteApp.name)
      const server = await createServer({ base, root: viteApp.path, server: { middlewareMode: true, ws: { port: hmrPort++ } }})
      viteServers.push({ base, root: viteApp.root, middlewares: server.middlewares })
    }

    const servicePrefixes = collectServicePrefixes()
    const isServiceRoute = url => servicePrefixes.some(p => url === p.replace(/\/$/, '') || url.startsWith(p))

    viteMiddleware = (req, res, next) => {
      const url = req.url || ''
      if (isServiceRoute(url)) return next()
      // Sub-folder vite apps: match by base prefix
      const sub = viteServers.find(v => !v.root && (url.startsWith(v.base) || url.startsWith('/@')))
      if (sub) return sub.middlewares(req, res, next)
      // Root vite app handles everything else; vite calls next() for unknown files
      const root = viteServers.find(v => v.root)
      if (root) return root.middlewares(req, res, next)
      next()
    }
  })
})
